<template>
<div class="boxb">
        <h4>用户信息</h4>
        <p class="acca">姓名:{{ informations.name }}</p>
        <br /><br />
        <p class="acca">学号:{{ informations.xuehao }}</p>
        <br /><br />
        <p class="acca">电话号码:{{ informations.phoneNumber }}</p>
        <br /><br />
        <p class="acca">取件次数:{{ informations.number }}</p>
        <br /><br /><br />
        <p class="accda">不想继续使用？点击下方注销</p>
        <button class="accca" v-on:@click.prevent="delete01()">注销</button>
    </div>
</template>
<script>
import { reactive } from "vue";
import axios from "axios";
import { useRoute } from "vue-router";
export default {
  created() {
    console.log(this.$route.query.name);
    console.log(this.$route.query.password);
  },
  name: "projectDemo02",
  setup() {
    const route = useRoute();
    const queryParams = reactive({
      name: route.query.name,
      password: route.query.password,
    });
    let informations = reactive({
      name: "",
      xuehao: "",
      phoneNumber: "",
      number: "",
    });
    function delete01() {
      var result = window.confirm("您确定要删除吗");
      if (result) {
        axios.delete("/untitiled/serve05", {
          xuehao: informations.xuehao,
        });
      } else {
        alert("好的");
      }
    }
    axios
      .get("/untitled/serve03/", {
        params: {
          name: queryParams.name,
          password: queryParams.password,
        },
      })
      .then((response) => {
        if (response.data.status == "success") {
          console.log("请求成功！", response.data);
          informations.name = response.data.name;
          informations.xuehao = response.data.xuehao;
          informations.phoneNumber = response.data.phoneNumber;
          informations.number = response.data.number;
        } else {
          /* router.push({ name: "projectDemo01" });*/
          console.log("false");
        }
      })
      .catch((error) => {
        console.error("请求失败：", error);
      });
    return {
      informations,
      delete01,
      queryParams,
    };
  },
};
</script>
