<template>
<div class="background">
  <div class="box">
        <h4>注册您的账户</h4>
        <iframe width="0" height="0" frameborder="0" id="myiframe" name="myiframe"></iframe>
        <br /><br />
        <input class="acc" type="text" name="names" maxlength="" v-model="information.name" placeholder="请输入您的姓名" /><br /><br />
        <input class="acc" type="text" name="xuehao" size="20" maxlength="10" v-model="information.message" placeholder="请输入您的学号" /><br /><br />
        <div class="accd">
            <input type="text" name="phone" size="17" maxlength="11" v-model="information.phoneNumber" placeholder="请输入您的手机号" />
            <button v-on:click="password()">发送验证码</button>
        </div>
        <br /><br />
        <input class="acc" type="text" name="yanzhengma" v-model="information.passwords.passwordss" maxlength="9" placeholder="请输入验证码" /><br />
        <br />
        <input class="acc" type="text" name="names" v-model="information.names" placeholder="请设置您的用户名" /><br /><br />
        <input class="acc" type="text" name="key" v-model="information.keys" placeholder="请设置您的密码" /><br /><br />
        <p>{{ information.tips }}</p>
        <button class="submit" v-on:click="sure()">确定</button>
    </div> 
</div>
</template>
<script>
import { reactive, watch } from "vue";
import axios from "axios";
import router from "@/router/router";
import qs from "qs";
import Project02 from "./project02.vue";
export default {
  components: Project02,
  name: "projectDemo01",
  setup() {
    let information = reactive({
      name: "",
      message: "",
      phoneNumber: "",
      keys: "",
      times: 0,
      tips: "",
      tips01: "",
      names: "",
      passwords: {
        passwordss: "",
      },
    });
    function timeout() {
      information.tips = "请在" + information.times + "秒后再次尝试";
      information.times--;
      if (information.times == 0) {
        information.tips = "";
      }
    }
    function password() {
      information.times = 60;
      axios
        .post(
          "/untitled/serve",
          qs.stringify({
            name: information.name,
            message: information.message,
            phoneNumber: information.phoneNumber,
          })
        )
        .then(function (response) {
          console.log(response.data.status);
          console.log(response.data.state_code);
          console.log(response.data.status == "success");
          if (response.data.status == "success") {
            var time = setInterval(timeout(), 1000);
            if (information.times == 0) {
              clearInterval(time);
            }
          }
        });
    }
    watch(information.times, (oldvalue, newvalue) => {
      information.times = newvalue;
      console.log(newvalue);
    });
    function sure() {
      axios
        .post(
          "/untitled/serve02",
          qs.stringify({
            name: information.name,
            message: information.message,
            phoneNumber: information.phoneNumber,
            names: information.names,
            key: information.keys,
            password01: information.passwords.passwordss,
          })
        )
        .then(function (response) {
          if (response.data.status == "success") {
            router.push({
              name: "projectDemo02",
              query: {
                name: information.names,
                password: information.keys,
              },
            });
          } else {
            information.tips01 = response.data.tips;
            alert(information.tips01);
          }
        });
    }
    return {
      information,
      sure,
      password,
    };
  },
};
</script>

