<template>
  <div class="box">
        <div class="left"></div>
        <div class="right">
        <h4>用户登录</h4>
        <input class="acc" type="text" name="names" v-model="information01.name" placeholder="请输入用户名"/><br /><br />
        <input class="acc" type="text" name="password" v-model="information01.password" placeholder="请输入密码"/><br /><br />
        <p>{{ information01.tips }}</p>
        <button class="accc" v-on:click="sure()">立即登录</button>
        </div>
    </div>
</template>
<script>
import axios from "axios";
import router from "@/router/router";
import qs from "qs";
import { reactive } from "vue";
export default {
  name: "projectDemo03",
  setup() {
    let information01 = reactive({
      name: "",
      password: "",
      tips: "",
    });
    function sure() {
      axios
        .post(
          "/untitled/serve04",
          qs.stringify({
            name: information01.name,
            password: information01.password,
          })
        )
        .then(function (response) {
          if (response.data.state_code == "success") {
            router.push({
              name: "projectDemo02",
              query: {
                name: encodeURIComponent(information01.name),
                password: information01.password,
              },
            });
          } else {
            information01.tips = "用户名或密码错误";
          }
        });
    }
    return {
      sure,
      information01,
    };
  },
};
</script>
<style  scoped>
