    height: 5rem;
    font-size: 1.6rem;
    margin-top: 5rem;
    padding: 1rem 0 0 1.6rem;
    border: none;
    border-bottom: 1px solid skyblue;
    color: skyblue;
    background-color: rgba(0, 0, 0, 0);
}

.box .right .acc:focus {
    outline: none;
