import { createRouter, createWebHashHistory } from 'vue-router'
import projectDemo01 from '../components/project01.vue'
import projectDemo02 from '../components/project02.vue'
import projectDemo03 from '@/components/project03.vue'
const router = createRouter({
    history: createWebHashHistory(process.env.BASE_URL),
    routes: [
        {
            path: "/project02", component: projectDemo02, name: "projectDemo02", props: true
        },
        {
            path: "/project01", component: projectDemo01, name: "projectDemo01"
        },
        {
            path: "/", redirect: "/project01", name: "projectDemo0"
        },
        {
            path: "/project03", component: projectDemo03, name: "projectDemo03"
        },
    ]

})
export default router